export function parseUtcString(dateString: string): Date {
  if (!dateString) return new Date();
  const [datePart, timePart] = dateString.split(' ');
  const [year, month, day] = datePart.split('-').map(Number);
  const [hours, minutes, seconds] = timePart.split(':').map(Number);
  return new Date(Date.UTC(year, month - 1, day, hours, minutes, seconds));
}

export const parseMonthYear = (monthYear: string) => {
  return new Date(Date.UTC(Number(monthYear.split('-')[0]), Number(monthYear.split('-')[1]) - 1));
};

export const monthYearToString = (monthYear: string, language: string) => {
  return parseMonthYear(monthYear).toLocaleString(language, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC'
  });
};
